# algebraic equations (name: expression of the other variables; L = line in subsystems.jl)
EQ = {
    "AGIW": lambda v: v.WARA * v.AHW,  # L78
    "AHW": lambda v: v.NHW / v.PFTJ,  # L79
    "AHW1980": lambda v: v.I_NHW / v.PFTJ80,  # L80
    "AVWO": lambda v: v.WAP * v.LPR,  # L81
    "CECLR": lambda v: v.ROCECLR * v.ECLR,  # L82
    "CHWO": lambda v: (v.OPWO - v.WF) / v.HFD,  # L83
    "CWSO": lambda v: v.WSO * v.ROCWSO,  # L84
    "CWRA": lambda v: v.WARA * v.ROCWSO,  # L85
    "GDPPEROCCLR": lambda v: max(0, 1 + v.GDPPEROCCLRM * (v.GDPP / v.GDPP1980 - 1)),  # L87
    "ENLPR2022": lambda v: ramp(v.t, v.GENLPR / v.IPP, 2022, 2022 + v.IPP),  # L88
    "HFD": lambda v: v.TYLD / 3,  # L89
    "HWMGDPP": lambda v: 1 + v.TENHW * (v.GDPP / v.GDPP1980 - 1),  # L90
    "IWEOCLR": lambda v: 1 + v.WSOECLR * (v.WSO / v.I_WSO - 1),  # L91
    "ILPR": lambda v: v.NLPR - v.PSW,  # L92
    "LAPR": lambda v: (v.OUTP * v.PRUN) / v.LAUS,  # L93
    "LAUS": lambda v: v.WF * v.AHW,  # L94
    "LAUS80": lambda v: v.I_WF * v.AHW1980,  # L95
    "LTEWSO": lambda v: v.WSO * v.RWER,  # L97
    "NLPR": lambda v: v.NLPR80 * (1 + v.WSOELPR * (v.WSO / v.I_WSO - 1)) + v.ENLPR2022,  # L99
    "OCLR": lambda v: v.ECLR * v.WEOCLR,  # L100
    "OPWO": lambda v: (v.CAP / v.OCLR) * v.PFTJ,  # L101
    "PART": lambda v: v.LPR * (1 - v.PURA),  # L102
    "PSW": lambda v: v.AUR * (1 + v.PUELPR * (v.PURA / v.AUR - 1)),  # L103
    "ROCECLR": lambda v: v.ROCECLR80 * v.GDPPEROCCLR,  # L105
    "ROCWSO": lambda v: withlookup(v.PURA / v.AUR, [(0.0, 0.06), (0.5, 0.02), (1.0, 0.0), (1.5, -0.007), (2.0, -0.01)]),  # L106
    "TCT": lambda v: v.TYLD / 3,  # L107
    "UNEM": lambda v: max(0, v.AVWO - v.WF),  # L108
    "UPT": lambda v: v.TYLD / 3,  # L109
    "UR": lambda v: v.UNEM / v.AVWO,  # L110
    "WAP": lambda v: v.A20PA,  # L111
    "WASH": lambda v: v.WARA / v.LAPR,  # L113
    "WRE": lambda v: v.WARA * v.WRER,  # L116
    "WRER": lambda v: v.IR * (1 - v.FIC),  # L117
}

# derivatives of the states (smooth!(x, input, T) is D(x) = (input - x) / T)
DER = {
    "ECLR": lambda v: v.CECLR,  # L86
    "LPR": lambda v: (v.ILPR - v.LPR) / (v.TELLM),  # L96
    "NHW": lambda v: (v.I_NHW * v.HWMGDPP - v.NHW) / (v.TAHW),  # L98
    "PURA": lambda v: (v.UR - v.PURA) / (v.UPT),  # L104
    "WARA": lambda v: v.CWRA - v.WRE,  # L112
    "WEOCLR": lambda v: (v.IWEOCLR - v.WEOCLR) / (v.TCT),  # L114
    "WF": lambda v: v.CHWO,  # L115
    "WSO": lambda v: v.CWSO - v.LTEWSO,  # L118
}


class LabourMarketSector(E4ASector):
    name = "e4a_labourmarket"
    SECTOR_KEY = "labourmarket"
    STATE_NAMES = STATE_NAMES
    PARAMS = PARAMS
    PARAMS_GL = PARAMS_GL
    PARAM_EXPR = PARAM_EXPR
    INITS = INITS
    STATE_INIT = STATE_INIT
    EQ = EQ
    DER = DER
    INPUT_NAMES = INPUT_NAMES
    inputs = {n: UNITS[n] for n in INPUT_NAMES}
    outputs = {n: UNITS[n] for n in list(EQ) + list(STATE_NAMES)}


SECTOR_CLASS = LabourMarketSector
